import React, { useState, useEffect } from "react";
import Select from '../../../ui/Select';
import { useEmbedded } from '../../embedded';

interface Category {
  maincategory_ko: string;
  maincategory_en: string;
  subcategories: {
    subcategory_ko: string;
    subcategory_en: string;
    subcategory_order: number;
  }[];
}

interface FAQCategoryRenameFormProps {
  renameData: {
    category_field: string;
    prev_category: string;
    new_category: string;
  };
  setRenameData: React.Dispatch<React.SetStateAction<any>>;
  categories: Category[];
  handleCategorySelect: (field: string, value: string) => void;
  handleRename: () => void;
  isUpdating: boolean;
}

const FAQCategoryRenameForm: React.FC<FAQCategoryRenameFormProps> = ({
  renameData,
  setRenameData,
  categories,
  handleCategorySelect,
  handleRename,
  isUpdating,
}) => {
  const emb = useEmbedded(); // 관리 탭 안에 끼워 넣었으면 상자·큰 제목 없이
  const [selectedMainCategory, setSelectedMainCategory] = useState<string>("");
  const [availableSubcategories, setAvailableSubcategories] = useState<string[]>([]);

  useEffect(() => {
    if (!renameData.category_field.includes("subcategory") || !selectedMainCategory) return;

    const selectedCategory = categories.find((cat) =>
      renameData.category_field === "subcategory_ko"
        ? cat.maincategory_ko === selectedMainCategory
        : cat.maincategory_en === selectedMainCategory
    );

    setAvailableSubcategories(
      selectedCategory
        ? renameData.category_field === "subcategory_ko"
          ? selectedCategory.subcategories.map(sub => sub.subcategory_ko)
          : selectedCategory.subcategories.map(sub => sub.subcategory_en)
        : []
    );
  }, [selectedMainCategory, renameData.category_field, categories]);

  return (
    <div className={emb ? '' : 'flex items-center justify-center py-6 sm:min-h-[calc(100vh-4.5rem)] sm:py-10'}> {/* 화면 가운데에 고정 */}
      <div className={emb ? 'w-full' : 'p-4 sm:p-6 bg-surface rounded-xl shadow-md w-full max-w-lg'}>
      {!emb && (<h1 className="text-xl sm:text-2xl font-bold text-ink text-center mb-6">FAQ 카테고리 이름 변경</h1>)}
      {!emb && <p className="text-center mb-4">해당되는 카테고리를 한번에 바꿀 수 있습니다.</p>}
    
      {/* 카테고리 유형 선택 */}
      <div className="mb-4">
        <label className="block text-lg font-medium text-ink mb-2">카테고리 유형 선택:</label>
        <Select
          value={renameData.category_field}
          onChange={(e) => handleCategorySelect("category_field", e.target.value)}
          className="w-full p-3 border border-line rounded-xl shadow-sm focus:ring-accent-ink/40 focus:border-accent-ink"
        >
          <option value="">카테고리 선택</option>
          <option value="maincategory_ko">주요 카테고리 (KO)</option>
          <option value="maincategory_en">주요 카테고리 (EN)</option>
          <option value="subcategory_ko">하위 카테고리 (KO)</option>
          <option value="subcategory_en">하위 카테고리 (EN)</option>
        </Select>
      </div>

      {/* 주요 카테고리 선택 (주요 카테고리 변경 시) */}
      {(renameData.category_field === "maincategory_ko" || renameData.category_field === "maincategory_en") && (
        <div className="mb-4">
          <label className="block text-lg font-medium text-ink mb-2">기존 주요 카테고리:</label>
          <Select
            value={renameData.prev_category}
            onChange={(e) => handleCategorySelect("prev_category", e.target.value)}
            className="w-full p-3 border border-line rounded-xl shadow-sm focus:ring-accent-ink/40 focus:border-accent-ink"
          >
            <option value="">주요 카테고리 선택</option>
            {categories.map((cat) => (
              <option
                key={cat.maincategory_ko}
                value={renameData.category_field === "maincategory_ko" ? cat.maincategory_ko : cat.maincategory_en}
              >
                {renameData.category_field === "maincategory_ko" ? cat.maincategory_ko : cat.maincategory_en}
              </option>
            ))}
          </Select>
        </div>
      )}

      {/* 하위 카테고리 변경 시, 먼저 주요 카테고리를 선택해야 함 */}
      {(renameData.category_field === "subcategory_ko" || renameData.category_field === "subcategory_en") && (
        <div className="mb-4">
          <label className="block text-lg font-medium text-ink mb-2">먼저 주요 카테고리를 선택하세요:</label>
          <Select
            value={selectedMainCategory}
            onChange={(e) => setSelectedMainCategory(e.target.value)}
            className="w-full p-3 border border-line rounded-xl shadow-sm focus:ring-accent-ink/40 focus:border-accent-ink"
          >
            <option value="">주요 카테고리 선택</option>
            {categories.map((cat) => (
              <option
                key={cat.maincategory_ko}
                value={renameData.category_field === "subcategory_ko" ? cat.maincategory_ko : cat.maincategory_en}
              >
                {renameData.category_field === "subcategory_ko" ? cat.maincategory_ko : cat.maincategory_en}
              </option>
            ))}
          </Select>

          {/* 선택된 주요 카테고리에 따른 하위 카테고리 목록 표시 */}
          {selectedMainCategory && (
            <div className="mt-4">
              <label className="block text-lg font-medium text-ink mb-2">기존 하위 카테고리:</label>
              <Select
                value={renameData.prev_category}
                onChange={(e) => handleCategorySelect("prev_category", e.target.value)}
                className="w-full p-3 border border-line rounded-xl shadow-sm focus:ring-accent-ink/40 focus:border-accent-ink"
              >
                <option value="">하위 카테고리 선택</option>
                {availableSubcategories.map((subcategory) => (
                  <option key={subcategory} value={subcategory}>
                    {subcategory}
                  </option>
                ))}
              </Select>
            </div>
          )}
        </div>
      )}

      {/* 새로운 카테고리 입력 필드 */}
      <div className="mb-4">
        <label className="block text-lg font-medium text-ink mb-2">새로운 카테고리:</label>
        <input
          type="text"
          value={renameData.new_category}
          onChange={(e) => handleCategorySelect("new_category", e.target.value)}
          placeholder="새 카테고리 입력"
          className="w-full p-3 border border-line rounded-xl shadow-sm focus:ring-accent-ink/40 focus:border-accent-ink"
        />
      </div>

      {/* 카테고리 변경 버튼 */}
      <button
        onClick={handleRename}
        disabled={isUpdating || !renameData.prev_category || !renameData.new_category}
        className={`w-full py-3 rounded-xl text-white font-bold transition ${
          isUpdating || !renameData.prev_category || !renameData.new_category
            ? "bg-card-3 cursor-not-allowed"
            : "bg-accent hover:bg-accent/90"
        }`}
      >
        {isUpdating ? "변경 중..." : "카테고리 이름 변경"}
      </button>
      </div>
      </div>
  );
};

export default FAQCategoryRenameForm;